const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const icon=n=>`<svg aria-hidden="true"><use href="#i-${n}"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let documents=[],selectedFile=null,extracting=false,db=null,questionItems=[],activeQuestion=null,currentURL=null,fileGeneration=0;
const labels={assistant:'Assistant',procedures:'Procédures',administration:'Administration'};
function navigate(){const view=location.hash.slice(1);const target=labels[view]?view:'assistant';$$('.view').forEach(v=>v.hidden=v.id!=='view-'+target);$$('.nav-link').forEach(a=>{a.classList.toggle('active',a.dataset.view===target);if(a.dataset.view===target)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$('#page-label').textContent=labels[target];closeMenu();if(target==='procedures')renderDocuments()}
window.addEventListener('hashchange',navigate);navigate();
function closeMenu(){$('#sidebar').classList.remove('open');$('#scrim').classList.remove('show');$('#mobile-menu').setAttribute('aria-expanded','false')}
$('#mobile-menu').onclick=()=>{$('#sidebar').classList.add('open');$('#scrim').classList.add('show');$('#mobile-menu').setAttribute('aria-expanded','true')};$('#scrim').onclick=closeMenu;document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});
$$('[data-go]').forEach(b=>b.onclick=()=>location.hash=b.dataset.go);
$('#help').onclick=$('#context-info').onclick=()=>$('#info-dialog').showModal();
$$('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());
$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
let toastTimer;function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200)}
const input=$('#question');function resize(){input.style.height='auto';input.style.height=Math.min(input.scrollHeight,150)+'px';$('#send').disabled=!input.value.trim()}
input.oninput=resize;input.onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();if(input.value.trim())$('#chat-form').requestSubmit()}};
$$('[data-question]').forEach(b=>b.onclick=()=>{input.value=b.dataset.question;resize();input.focus()});
$('#new-question').onclick=()=>{location.hash='assistant';activeQuestion=null;$('#welcome').hidden=false;$('#conversation').innerHTML='';input.value='';resize();input.focus()};
$('#chat-form').onsubmit=e=>{e.preventDefault();const text=input.value.trim();if(!text)return;questionItems.push({id:crypto.randomUUID(),text});activeQuestion=questionItems.at(-1);renderQuestion(activeQuestion);input.value='';resize();renderRecent()};
function renderQuestion(q){$('#welcome').hidden=true;$('#conversation').innerHTML=`<div class="message user"><p>${esc(q.text)}</p></div><div class="message"><div class="reply-label">${icon('shield')}LABGUARD</div><div class="answer"><h3>La recherche documentaire n’est pas encore active.</h3><p>Votre question n’a pas été analysée. La passerelle vers la base du laboratoire doit être activée avant de pouvoir proposer une conduite à tenir sourcée.</p><p>Vous pouvez déjà préparer et vérifier vos procédures dans l’espace documentaire.</p><button class="text-link" id="answer-procedures">Consulter les procédures ${icon('arrow')}</button><div class="answer-status">Aucune conclusion pré-analytique générée · Question conservée dans cette session uniquement</div></div></div>`;$('#answer-procedures').onclick=()=>location.hash='procedures';$('#chat-scroll').scrollTop=0}
function renderRecent(){$('#recent-list').innerHTML=questionItems.slice(-10).reverse().map(q=>`<button data-session="${q.id}" title="${esc(q.text)}">${esc(q.text)}</button>`).join('');$$('[data-session]').forEach(b=>b.onclick=()=>{location.hash='assistant';activeQuestion=questionItems.find(q=>q.id===b.dataset.session);renderQuestion(activeQuestion)})}
async function openDB(){db=await new Promise((resolve,reject)=>{const r=indexedDB.open('labguard-document-preparation',1);r.onupgradeneeded=()=>r.result.createObjectStore('documents',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});documents=await readAll();renderDocuments()}
function readAll(){return new Promise((resolve,reject)=>{const t=db.transaction('documents','readonly');const r=t.objectStore('documents').getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function mutate(op,record){return new Promise((resolve,reject)=>{const t=db.transaction('documents','readwrite');t.objectStore('documents')[op](record);t.oncomplete=resolve;t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error)})}
function renderDocuments(){$$('.doc-count').forEach(x=>x.textContent=documents.length);const term=$('#doc-search').value.toLocaleLowerCase('fr'),status=$('#doc-filter').value;const result=documents.filter(d=>(status==='all'||d.status===status)&&[d.title,d.code,d.version].join(' ').toLocaleLowerCase('fr').includes(term)).sort((a,b)=>b.created-a.created);$('#document-list').innerHTML=result.length?result.map(d=>`<button class="document-row" data-document="${esc(d.id)}"><span class="doc-icon">${icon('doc')}</span><span><strong>${esc(d.title)}</strong><small>${esc(d.code)} · v${esc(d.version)} · ${esc(d.department)} · ${d.pages?d.pages+' page'+(d.pages>1?'s':''):'Sans pagination'}</small></span><span class="doc-status ${d.status==='reviewed'?'ready':''}">${d.status==='reviewed'?'Prêt à intégrer':'Brouillon'}</span>${icon('chevron')}</button>`).join(''):`<div class="empty-library"><div class="empty-icon">${icon('book')}</div><h2>${documents.length?'Aucun document correspondant.':'Votre bibliothèque commence ici.'}</h2><p>${documents.length?'Modifiez votre recherche ou le filtre pour retrouver un document.':'Ajoutez une première procédure, vérifiez son contenu et préparez sa future utilisation dans LabGuard.'}</p>${!documents.length?'<button class="primary" id="empty-import">'+icon('plus')+'Ajouter une procédure</button>':''}</div>`;$('#empty-import')?.addEventListener('click',openImport);$$('[data-document]').forEach(b=>b.onclick=()=>showDocument(b.dataset.document))}
$('#doc-search').oninput=renderDocuments;$('#doc-filter').onchange=renderDocuments;
function openImport(){fileGeneration++;$('#import-form').reset();selectedFile=null;extracting=false;$('#save-document').disabled=true;$('#file-label').textContent='Choisir un document';$('#file-status').textContent='';$('#page-count').textContent='';$('#form-error').textContent='';$('#import-dialog').showModal()}
$$('[data-import]').forEach(b=>b.onclick=openImport);
$('#file-input').onchange=()=>processFile($('#file-input').files[0]);
const drop=$('#dropzone');['dragenter','dragover'].forEach(ev=>drop.addEventListener(ev,e=>{e.preventDefault();drop.classList.add('dragging')}));['dragleave','drop'].forEach(ev=>drop.addEventListener(ev,e=>{e.preventDefault();drop.classList.remove('dragging')}));drop.addEventListener('drop',e=>processFile(e.dataTransfer.files[0]));
async function extractPDF(file){const pdfjs=await import('/vendor/pdf.mjs');pdfjs.GlobalWorkerOptions.workerSrc='/vendor/pdf.worker.mjs';const task=pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer()),isEvalSupported:false});const pdf=await task.promise;try{if(pdf.numPages>250)throw new Error('Document trop long : 250 pages maximum pour cette préparation locale.');const pages=[];for(let i=1;i<=pdf.numPages;i++){const page=await pdf.getPage(i);const content=await page.getTextContent();let text='';for(const item of content.items)if('str'in item)text+=item.str+(item.hasEOL?'\n':' ');pages.push({number:i,text:text.trim()});page.cleanup()}return {text:pages.map(p=>`[Page ${p.number}]\n${p.text}`).join('\n\n'),pages:pdf.numPages,hasText:pages.some(p=>p.text.length>20)}}finally{await pdf.destroy()}}
async function extractDOCX(file){const buffer=await file.arrayBuffer();const bytes=new Uint8Array(buffer),v=new DataView(buffer);let end=-1;for(let i=bytes.length-22;i>=Math.max(0,bytes.length-65557);i--){if(v.getUint32(i,true)===0x06054b50){end=i;break}}if(end<0)throw new Error('Fichier DOCX illisible.');let offset=v.getUint32(end+16,true);const count=v.getUint16(end+10,true);for(let i=0;i<count;i++){if(v.getUint32(offset,true)!==0x02014b50)throw new Error('Archive DOCX invalide.');const method=v.getUint16(offset+10,true),size=v.getUint32(offset+20,true),unpacked=v.getUint32(offset+24,true),len=v.getUint16(offset+28,true),extra=v.getUint16(offset+30,true),comment=v.getUint16(offset+32,true),local=v.getUint32(offset+42,true);const name=new TextDecoder().decode(bytes.slice(offset+46,offset+46+len));if(name==='word/document.xml'){if(unpacked>8*1024*1024)throw new Error('Contenu décompressé trop volumineux.');const start=local+30+v.getUint16(local+26,true)+v.getUint16(local+28,true);let xml;if(method===0)xml=new TextDecoder().decode(bytes.slice(start,start+size));else if(method===8){const reader=new Blob([bytes.slice(start,start+size)]).stream().pipeThrough(new DecompressionStream('deflate-raw')).getReader();const chunks=[];let total=0;while(true){const {done,value}=await reader.read();if(done)break;total+=value.length;if(total>8*1024*1024){await reader.cancel();throw new Error('Contenu trop volumineux.')}chunks.push(value)}xml=await new Blob(chunks).text()}else throw new Error('Compression DOCX non prise en charge.');const doc=new DOMParser().parseFromString(xml,'application/xml');if(doc.querySelector('parsererror'))throw new Error('Le contenu Word est illisible.');return {text:[...doc.getElementsByTagNameNS('*','p')].map(p=>[...p.getElementsByTagNameNS('*','t')].map(t=>t.textContent).join('')).join('\n'),pages:null,hasText:true}}offset+=46+len+extra+comment}throw new Error('Texte principal absent du DOCX.')}
async function processFile(file){if(!file)return;const generation=++fileGeneration;$('#form-error').textContent='';$('#save-document').disabled=true;selectedFile=null;extracting=true;$('#extracted').value='';$('#page-count').textContent='';try{if(file.size>10*1024*1024)throw new Error('Le fichier dépasse la limite de 10 Mo.');const ext=file.name.split('.').pop().toLowerCase();if(!['pdf','docx','txt'].includes(ext))throw new Error('Choisissez un fichier PDF, DOCX ou TXT.');$('#file-label').textContent=file.name;$('#file-status').textContent='Lecture du document dans votre navigateur…';let result;if(ext==='pdf')result=await extractPDF(file);else if(ext==='docx')result=await extractDOCX(file);else result={text:await file.text(),pages:null,hasText:true};if(generation!==fileGeneration)return;if(result.text.length>1500000)throw new Error('Texte trop long pour cette préparation locale.');selectedFile={file,pages:result.pages};$('#extracted').value=result.text;$('#page-count').textContent=result.pages?result.pages+' page'+(result.pages>1?'s':''):'Sans pagination';$('#file-status').textContent=result.hasText?'Extraction terminée. Vérifiez le contenu avant l’enregistrement.':'Aucun texte exploitable. PDF probablement scanné : ajoutez une transcription vérifiée ou importez un PDF avec texte.';if(!$('#import-form').elements.title.value)$('#import-form').elements.title.value=file.name.replace(/\.[^.]+$/,'');}catch(e){if(generation===fileGeneration){$('#file-status').textContent='Lecture interrompue.';$('#form-error').textContent=e.message||'Impossible de lire ce document. Essayez un PDF texte.'}}finally{if(generation===fileGeneration){extracting=false;$('#save-document').disabled=!selectedFile||!db}}}
$('#import-form').onsubmit=async e=>{e.preventDefault();if(!selectedFile||extracting||!db)return;const form=e.currentTarget;const content=$('#extracted').value.trim();if(content.length<30){$('#form-error').textContent='Ajoutez au moins 30 caractères de texte vérifié avant de sauvegarder.';return}if(!form.elements.title.value.trim()||!form.elements.code.value.trim()||!form.elements.version.value.trim()){$('#form-error').textContent='Renseignez le titre, le code et la version.';return}$('#save-document').disabled=true;try{const record={id:crypto.randomUUID(),title:form.elements.title.value.trim(),code:form.elements.code.value.trim(),version:form.elements.version.value.trim(),department:form.elements.department.value,effective:form.elements.effective.value,responsible:form.elements.responsible.value.trim(),status:form.elements.reviewed.checked?'reviewed':'draft',pages:selectedFile.pages,content,file:selectedFile.file,filename:selectedFile.file.name,created:Date.now()};await mutate('put',record);documents=await readAll();renderDocuments();$('#import-dialog').close();location.hash='procedures';toast('Document enregistré dans ce navigateur. Aucune synchronisation serveur.')}catch(e){$('#form-error').textContent='Enregistrement impossible. Vérifiez l’espace disponible et l’autorisation du stockage dans ce navigateur.'}finally{$('#save-document').disabled=false}};
function showDocument(id){const d=documents.find(x=>x.id===id);if(!d)return;$('#detail-title').textContent=d.title;$('#document-detail').innerHTML=`<div class="detail-meta"><div><span>Code · Version</span><strong>${esc(d.code)} · ${esc(d.version)}</strong></div><div><span>Contexte</span><strong>Ixelles · ${esc(d.department)}</strong></div><div><span>État de préparation</span><strong>${d.status==='reviewed'?'Prêt à intégrer':'Brouillon à vérifier'}</strong></div><div><span>Entrée en vigueur</span><strong>${esc(d.effective||'Non renseignée')}</strong></div><div><span>Responsable documentaire</span><strong>${esc(d.responsible||'Non renseigné')}</strong></div><div><span>Fichier original</span><strong>${esc(d.filename)}</strong></div></div><p>Ce document est stocké localement. Il ne fait pas encore partie des sources du tchat.</p><div class="detail-actions"><button class="secondary" id="download-original">${icon('doc')}Télécharger l’original</button><button class="danger" id="delete-document">Supprimer le brouillon local</button></div><div class="detail-text">${esc(d.content)}</div>`;$('#download-original').onclick=()=>{if(currentURL)URL.revokeObjectURL(currentURL);currentURL=URL.createObjectURL(d.file);const a=document.createElement('a');a.href=currentURL;a.download=d.filename;a.click()};$('#delete-document').onclick=async()=>{if(!confirm('Supprimer ce document de ce navigateur ? Le fichier original sur votre ordinateur restera intact.'))return;try{await mutate('delete',id);documents=await readAll();renderDocuments();$('#document-dialog').close();toast('Document local supprimé.')}catch{toast('Impossible de supprimer le document.')}};$('#document-dialog').showModal()}
$('#document-dialog').addEventListener('close',()=>{if(currentURL){URL.revokeObjectURL(currentURL);currentURL=null}});
openDB().catch(()=>{toast('Stockage local indisponible. L’import ne pourra pas être enregistré dans ce navigateur.');renderDocuments()});
